clear all; clc; close all;
%[text]{"align":"center"} # <u>Model-Based and Data-Driven Co-Design of Robust DC Microgrids using Dissipativity</u>
%[text] ## 1. Generating a Random DC MicrogridNN
rng(7);
saveImages = 0;
linkFiltThresh = 1e-4;
N = 4;    % number of DGs  

% Generate a DC Microgrid
net = getARandomDCMicrogrid(N); %[output:65e63f38] %[output:3c19b36f]

% Draw topology and initial condition
fig = figure('Color','w','Name','DC Microgrid Example'); %[output:248d1f9f]
figure(fig); clf;  %[output:248d1f9f]
ax = axes(fig); net.draw(ax); %[output:248d1f9f]

% Save Figure
if saveImages
    adjustAxesPadding(ax, 0, 0, 0, 0);
    saveFigureHighRes('DCMG', ...
        'Width', 6, 'Height', 6, 'Units', 'inches', ...
        'DPI', 600, 'FontSize', 6);
end

% Simulation data
dt_system = 1e-5;
tspan = 0:dt_system:0.2;          % seconds
dt_noise = 1e-5;
sigma_noise = 0.00001*diag([1; 1]);      % Noise variance in I_i and V_{ti} channels
net.setupNoise(tspan, dt_noise, sigma_noise);   % dt_noise, sigma

% Save the network
save("netFile","net","saveImages","linkFiltThresh","tspan","N");
%%
%[text] ## 2. Model-Based Global Stabilizing Controller
clear all; clc; close all;
rng(7);
load netFile.mat;
figTitle = 'MB-GSC' %[output:63a3b0b4]
useData = 0;

% Model-based design of a global stabilizing controller 
[AdjMat, KMat, out] = net.design_MB_GSC(linkFiltThresh,useData); %[output:54710e3b]

% Draw topology 
fig = figure('Color','w','Name',[figTitle,'-Topology']); %[output:9bb8f073]
figure(fig); clf;  %[output:9bb8f073]
ax = axes(fig);  %[output:9bb8f073]
net.draw(ax); %[output:9bb8f073]

% Save Figure
if saveImages
    adjustAxesPadding(ax, 0, 0, 0, 0);
    saveFigureHighRes([figTitle,'-Topology'], ...
        'Width', 6, 'Height', 6, 'Units', 'inches', ...
        'DPI', 600, 'FontSize', 6);
end

% Simulating
x0 = net.getStateVector();
[t, X, U, Xs, Us] = net.simulate(tspan, x0, useData); %[output:161150b3] %[output:1c56d572] %[output:5330395d]
trajDataPU = drawStateTrajectories(t,X,U,Xs,Us,N,saveImages,figTitle); %[output:72a67392] %[output:6863d0df]
%%
%[text] ## 3. Model-Based Co-Designed Distributed Robust Controller
clear all; clc; close all;
rng(7);
load netFile.mat;
useData = 0;
figTitle = 'MB-DRC' %[output:28c5cda3]

% Model-based co-design of a distributed robust controller
[AdjMat, KMat, out] = net.codesign_MB_DRC(linkFiltThresh); %[output:7f653865] %[output:82b8fd80] %[output:252ab768] %[output:9c8bc70c] %[output:8fcf6742] %[output:952cb547] %[output:119b8a6b] %[output:66c87903] %[output:7862fe87] %[output:2f3f6983] %[output:6cca7436] %[output:9ea52e4f] %[output:50ca1e5f] %[output:8329f46f] %[output:21ed5bef]

