    saveFigureHighRes([figTitle,'-Topology'], ...
            'Width', 6, 'Height', 6, 'Units', 'inches', ...
            'DPI', 600, 'FontSize', 6);
end

% Simulating
x0 = net.getStateVector();
useData = 0;
[t, X, U, Xs, Us] = net.simulate(tspan, x0, useData); %[output:81eb6df0] %[output:84f0eb98] %[output:1aa49c55]
