[t, X, U, Xs, Us] = net.simulate(tspan, x0, useData, linkFiltThresh); %[output:22264d97] %[output:8f1f8246] %[output:6868b8c7] %[output:3eb78cf1] %[output:9730b876] %[output:92e3430a] %[output:1e97ebdb] %[output:4e1384bb] %[output:44e5a1e5] %[output:326f9d4d] %[output:3b54e79e] %[output:85ac0cb5] %[output:18c4d22b] %[output:1d57612f] %[output:364c1e82] %[output:44969ee3] %[output:7fbb536c] %[output:93a462ad] %[output:48aeb3e8] %[output:811dd75a] %[output:1a580147] %[output:781308be] %[output:229033d1] %[output:8866e105] %[output:75a07cd0] %[output:660c043b] %[output:23f20883] %[output:0ec7e834] %[output:57de55c6] %[output:3604feba] %[output:3b26ddca] %[output:40767c3e] %[output:63f542ce] %[output:94194ee2] %[output:9b526ac0] %[output:26447f2c] %[output:289a5744] %[output:578d23ba] %[output:97f401f7] %[output:2ce4ad4d] %[output:18d980ca] %[output:07e132ca]
